-- Run after importing CSV employee IDs explicitly. This makes the next ID
-- generated by employees.employee_id greater than every existing emp_N value.
select setval(
    'public.employee_number_seq',
    greatest(
        coalesce((
            select max(substring(employee_id from '^emp_([0-9]+)$')::bigint)
            from public.employees
            where employee_id ~ '^emp_[0-9]+$'
        ), 0),
        1
    ),
    exists (select 1 from public.employees where employee_id ~ '^emp_[0-9]+$')
);
